const ACTIVITY_CATEGORIES=['Authentication','Navigation','Forms','PQS','Assessments','Administration','Calendar','Security','Files','System'];
function database(env){need(env.DB,'The activity and calendar database is unavailable. Contact the administrator.',503);return env.DB}
async function writeActivity(env,event){await database(env).prepare('INSERT INTO activity_events (id,at,request_id,user_id,actor_email,role,category,action,phase,status,method,path,demonstration,details) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),now(),event.requestId,event.userId||'',event.email||'Unknown or unsigned visitor',event.role||'unassigned',event.category,event.action,event.phase,event.status??null,event.method,event.path,event.demonstration?1:0,JSON.stringify(event.details||{})).run()}
function actionCategory(action,path){if(action.startsWith('daily-pqs-'))return 'Forms';if(path.includes('/calendar')||path.includes('/reminders'))return 'Calendar';if(path.includes('/reference-upload')||path.includes('/references/')||path.includes('/evidence/')||path.endsWith('/upload')||path.endsWith('/report'))return 'Files';if(path.includes('/presentation')||path.includes('/config')||path.includes('/activity'))return 'Administration';if(['response','feedback','shift','submit-shift','review-shift','review-response','review-feedback'].includes(action))return 'Forms';if(['skill','scenario','remediation','close-remediation','phase-request','phase-review'].includes(action))return 'PQS';if(path.includes('/exam')||['lesson','start-exam','save-exam','submit-exam','authorize-exam'].includes(action))return 'Assessments';return 'System'}
async function auditRequest(request,env,run){
 const url=new URL(request.url),requestId=crypto.randomUUID();let action=request.method+' '+url.pathname,posted={};
 if(request.method==='POST'&&(request.headers.get('Content-Type')||'').includes('application/json')){try{posted=await request.clone().json();if(typeof posted.action==='string')action=posted.action.slice(0,100)}catch{}}
 let a=null;try{const cfg=await configuration(env);a=actor(request,cfg.value)}catch{}
 const event={requestId,userId:request.headers.get('oai-authenticated-user-id')||'',email:(request.headers.get('oai-authenticated-user-email')||'').slice(0,200).toLowerCase(),role:a?.role||'unassigned',category:actionCategory(action,url.pathname),action,method:request.method,path:url.pathname.slice(0,400),demonstration:request.headers.get('X-REU-Presentation')==='1',details:{}};
 const target=url.pathname.match(/\/(?:trainees|calendar)\/([a-zA-Z0-9_-]+)/);if(target)event.details.traineeId=target[1];for(const key of ['shiftId','skillId','scenarioId','credentialId','planId','recordId','decision'])if(typeof posted[key]==='string')event.details[key]=posted[key].slice(0,120);if(posted.member&&typeof posted.member.email==='string'){event.details.targetEmail=posted.member.email.slice(0,200);event.details.assignedRole=posted.member.role;}if(posted.person){if(typeof posted.person.name==='string')event.details.traineeName=posted.person.name.slice(0,120);if(typeof posted.person.license==='string')event.details.license=posted.person.license.slice(0,30);}
 if(event.demonstration)event.details.presentationRole=['admin','trainer','trainee'].includes(request.headers.get('X-REU-Presentation-Role'))?request.headers.get('X-REU-Presentation-Role'):'unknown';
 if(url.pathname.endsWith('/events')){event.category=posted.action==='session-open'?'Authentication':'Navigation';event.action=posted.action||'client-event';if(typeof posted.page==='string')event.details.page=posted.page.slice(0,120);if(typeof posted.title==='string')event.details.title=posted.title.slice(0,150);event.details.source='Browser-reported activity'}
 if(url.pathname.endsWith('/bootstrap')&&!a)event.category='Security';
 try{await writeActivity(env,{...event,phase:'Attempt'})}catch{return out({error:'Activity logging is unavailable. Please retry shortly; the request was not processed.'},503)}
 let response;try{response=await run()}catch(e){response=out({error:e instanceof ApiError?e.message:'The request could not be completed. Refresh and try again.'},e.status||500)}
 try{await writeActivity(env,{...event,category:[401,403].includes(response.status)?'Security':event.category,phase:response.status<400?'Completed':'Denied or failed',status:response.status})}catch{console.error('Activity outcome unavailable for request '+requestId)}
 response.headers.set('X-REU-Request-ID',requestId);return response;
}
async function activityApi(request,env,url,a){
 if(url.pathname==='/api/academy/events'){need(request.method==='POST','Use POST.',405);const b=await body(request);need(['session-open','page-view','form-open','signout-intent','reminder-shown'].includes(b.action),'Unknown activity event.');return out({ok:true})}
 if(url.pathname!=='/api/academy/activity')return null;
 need(a.role==='admin','The website activity log is restricted to administrators.',403);need(request.method==='GET','Activity history is read-only.',405);
 const params=url.searchParams,limit=Math.min(100,Math.max(1,Number(params.get('limit'))||50)),where=[],values=[];
 if(env.presentationOwner){where.push('demonstration = 1 AND user_id = ?');values.push(env.presentationOwner)}else if(params.get('includeDemo')!=='1'){where.push('demonstration = 0')}
 const category=params.get('category');if(category){need(ACTIVITY_CATEGORIES.includes(category),'Unknown activity category.');where.push('category = ?');values.push(category)}
 const query=(params.get('q')||'').trim().slice(0,120);if(query){where.push('(actor_email LIKE ? OR action LIKE ? OR path LIKE ? OR details LIKE ?)');values.push(...Array(4).fill('%'+query+'%'))}
 for(const [param,op]of [['from','>='],['to','<=']]){const date=params.get(param);if(date){need(/^\d{4}-\d{2}-\d{2}$/.test(date),'Use a valid date filter.');where.push('at '+op+' ?');values.push(date+(param==='to'?'T23:59:59.999Z':'T00:00:00.000Z'))}}
 const before=params.get('before');if(before){let cur;try{cur=JSON.parse(atob(before))}catch{throw new ApiError('Invalid activity cursor.')}need(Array.isArray(cur)&&cur.length===2&&cur.every(v=>typeof v==='string'&&v.length<100),'Invalid activity cursor.');where.push('(at < ? OR (at = ? AND id < ?))');values.push(cur[0],cur[0],cur[1])}
 const result=await database(env).prepare('SELECT * FROM activity_events'+(where.length?' WHERE '+where.join(' AND '):'')+' ORDER BY at DESC,id DESC LIMIT ?').bind(...values,limit+1).all();const rows=result.results||[],hasMore=rows.length>limit,events=rows.slice(0,limit).map(e=>({...e,details:JSON.parse(e.details)}));const last=events.at(-1);return out({events,next:hasMore&&last?btoa(JSON.stringify([last.at,last.id])):null,categories:ACTIVITY_CATEGORIES,scope:'Application activity only. Sign-in attempts blocked by the hosting platform before reaching this website are not available here.'});
}

const CAL_ZONE='America/Detroit',wallFormatters=new Map();
