function calendarIdentity(env,id){return env.presentationOwner?'demo:'+env.presentationOwner+':'+id:id}
async function calendarSettings(env,id){return database(env).prepare('SELECT * FROM shift_calendars WHERE trainee_id = ?').bind(calendarIdentity(env,id)).first()}
async function importShifts(env,p,a,parsed,sourceUrl='',sourceType='file'){const archived=(await enrollment(env,p.id)).value;need(!archived.paperworkCleared&&!archived.cleanupPending,'Archived trainee calendars are closed.',409);const db=database(env),id=calendarIdentity(env,p.id),at=now(),rows=[];for(const e of parsed.events){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(id+'|'+e.uid)),key=[...new Uint8Array(digest)].map(n=>n.toString(16).padStart(2,'0')).join('').slice(0,40);rows.push({id:key,uid:e.uid,title:e.title,start:e.start,end:e.end})}
 const statements=[db.prepare('UPDATE scheduled_shifts SET cancelled = 1 WHERE trainee_id = ?').bind(id),db.prepare("INSERT INTO scheduled_shifts (id,trainee_id,event_uid,title,start_at,end_at,cancelled,imported_at) SELECT json_extract(value,'$.id'),?,json_extract(value,'$.uid'),json_extract(value,'$.title'),json_extract(value,'$.start'),json_extract(value,'$.end'),0,? FROM json_each(?) WHERE true ON CONFLICT(id) DO UPDATE SET title=excluded.title,start_at=excluded.start_at,end_at=excluded.end_at,cancelled=0,imported_at=excluded.imported_at").bind(id,at,JSON.stringify(rows)),db.prepare('INSERT INTO shift_calendars (trainee_id,source_url,source_type,timezone,last_sync,error,updated_by,updated_at) VALUES (?,?,?,?,?,NULL,?,?) ON CONFLICT(trainee_id) DO UPDATE SET source_url=excluded.source_url,source_type=excluded.source_type,last_sync=excluded.last_sync,error=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at').bind(id,sourceUrl||null,sourceType,CAL_ZONE,at,a.email,at)];await db.batch(statements);return {imported:parsed.events.length,skipped:parsed.skipped,lastSync:at}}
function aladtecUrl(value){let u;try{u=new URL(String(value).trim().replace(/^webcal:/i,'https:'))}catch{throw new ApiError('Paste the individual REU Aladtec iCalendar subscription link.')}need(u.protocol==='https:'&&u.hostname==='secure13.aladtec.com'&&!u.port&&!u.username&&!u.password&&u.pathname==='/reu/index.php'&&u.searchParams.get('action')==='ical_sync'&&u.searchParams.get('uid'),'Use the individual REU Aladtec HTTPS calendar subscription link.');return u.toString()}
async function fetchShifts(env,p,a,url){const response=await fetch(aladtecUrl(url),{headers:{Accept:'text/calendar'},redirect:'manual',signal:AbortSignal.timeout(20000)});need(response.ok,'Aladtec returned '+response.status+'. Check that the individual subscription is active.',502);need(Number(response.headers.get('content-length')||0)<=2000000,'The calendar is too large. Use an individual subscription.',413);const parsed=await parseShiftCalendar(await response.text());return importShifts(env,p,a,parsed,url,'subscription')}
function paperworkState(event,d,role){const candidates=live(d.shifts).filter(s=>s.scheduleId===event.id||Math.abs(Date.parse(s.start)-Date.parse(event.start_at))<=90*60000&&Math.abs(Date.parse(s.end)-Date.parse(event.end_at))<=90*60000).sort((a,b)=>Math.abs(Date.parse(a.start)-Date.parse(event.start_at))-Math.abs(Date.parse(b.start)-Date.parse(event.start_at))),shift=candidates[0],submitted=v=>['Submitted','Reviewed'].includes(v?.status);const missing=[];if(role!=='trainee'&&!submitted(shift))missing.push('FTO shift evaluation');if(role!=='trainer'){if(!submitted(shift?.traineeResponse))missing.push('Trainee shift response');if(!submitted(shift?.trainerFeedback))missing.push('Private FTO feedback')}if(shift&&(shift.pqsRequired||shift.dailyPqs)){if(role!=='trainer'&&!['Submitted','Signed','Reviewed'].includes(shift.dailyPqs?.status))missing.push('Trainee daily PQS checklist');if(role!=='trainee'&&!['Signed','Reviewed'].includes(shift.dailyPqs?.status))missing.push('FTO daily PQS sign-off')}return {shiftId:shift?.id||null,missing,complete:missing.length===0,waitingForFto:role==='trainee'&&!shift,reviewComplete:shift?shiftComplete(shift):false}}
async function scheduledRows(env,p,a){const result=await database(env).prepare('SELECT * FROM scheduled_shifts WHERE trainee_id = ? AND cancelled = 0 ORDER BY start_at').bind(calendarIdentity(env,p.id)).all(),{value:d}=await enrollment(env,p.id);if(a.role==='trainer'&&d.assignment?.ftoEmail!==a.email)return [];return (result.results||[]).map(e=>({id:e.id,traineeId:p.id,title:e.title,start:e.start_at,end:e.end_at,...paperworkState(e,d,a.role)}))}
async function calendarApi(request,env,url,a,c){if(url.pathname==='/api/academy/reminders'){need(request.method==='GET','Use GET.',405);const due=[];for(const p of c.people.filter(p=>p.active!==false&&assigned(a,p))){if(a.role==='trainer'&&(await enrollment(env,p.id)).value.assignment?.ftoEmail!==a.email)continue;const archiveState=(await enrollment(env,p.id)).value;if(archiveState.paperworkCleared||archiveState.cleanupPending)continue;const stored=await calendarSettings(env,p.id);if(stored?.source_url&&Date.now()-Date.parse(stored.updated_at||stored.last_sync)>15*60000){let success=false;try{await fetchShifts(env,p,a,stored.source_url);success=true}catch{await database(env).prepare('UPDATE shift_calendars SET error = ?,updated_at = ? WHERE trainee_id = ?').bind('Automatic sync failed; previous shifts retained.',now(),calendarIdentity(env,p.id)).run()}await writeActivity(env,{requestId:crypto.randomUUID(),userId:a.id,email:a.email,role:a.role,category:'Calendar',action:'Automatic Aladtec sync',phase:success?'Completed':'Denied or failed',status:success?200:502,method:'GET',path:'/api/academy/reminders',demonstration:!!env.presentationOwner,details:{traineeId:p.id}})}const rows=await scheduledRows(env,p,a);for(const e of rows)if(Date.parse(e.start)<=Date.now()&&Date.parse(e.end)-3600000<=Date.now()&&Date.parse(e.end)>=wallDate([...p.startDate.split('-').map(Number),0,0,0],CAL_ZONE)&&!e.complete)due.push({...e,trainee:p.name,overdue:Date.now()>Date.parse(e.end)+12*3600000})}return out({due,serverTime:now(),leadMinutes:60,repeatMinutes:10,delivery:'Reminders appear while the academy is open. Closed-browser delivery is not configured.'})}
 const m=url.pathname.match(/^\/api\/academy\/calendar\/([a-zA-Z0-9_-]+)$/);if(!m)return null;const p=person(c,a,m[1]);if(request.method==='GET'){const settings=await calendarSettings(env,p.id);return out({calendar:settings?{connected:!!settings.source_url,sourceType:settings.source_type,timezone:settings.timezone,lastSync:settings.last_sync,error:settings.error}:null,events:await scheduledRows(env,p,a)})}
 need(request.method==='POST','Use GET or POST.',405);const b=await body(request);if(b.action==='disconnect'){need(a.role==='admin'||a.role==='trainee','An administrator or the linked trainee can disconnect this feed.',403);await database(env).prepare('UPDATE shift_calendars SET source_url = NULL,source_type = ?,updated_by = ?,updated_at = ? WHERE trainee_id = ?').bind('disconnected',a.email,now(),calendarIdentity(env,p.id)).run();return out({ok:true})}
 if(b.action==='file'){need(b.individual===true,'Confirm that this calendar contains only the selected trainee’s shifts.');return out(await importShifts(env,p,a,await parseShiftCalendar(b.ics)))}
 if(b.action==='connect'){need(b.individual===true,'Confirm that this subscription is for the selected trainee only.');const url=aladtecUrl(b.url);try{return out(await fetchShifts(env,p,a,url))}catch(e){if(e instanceof ApiError)throw e;throw new ApiError('The calendar could not be reached. Check the subscription or import an ICS file. Existing shifts were kept.',502)}}
 if(b.action==='sync'){const current=await calendarSettings(env,p.id);need(current?.source_url,'Connect an individual Aladtec subscription first.');try{return out(await fetchShifts(env,p,a,current.source_url))}catch(e){await database(env).prepare('UPDATE shift_calendars SET error = ?,updated_at = ? WHERE trainee_id = ?').bind('Sync failed. Check the active subscription; previous shifts are retained.',now(),calendarIdentity(env,p.id)).run();throw new ApiError('Aladtec sync failed. Your previous shifts were kept. Check the subscription or import an ICS file.',502)}}
 throw new ApiError('Unknown calendar action.');
}

// Demonstration workspaces are retired. Old links cannot activate sample roles.
