// Daily REU source-PQS learning exposure and authenticated evaluator confirmation.
function dailyPqsItems(p,phase){return (CATALOG.dailyPqs.phases.find(x=>x.phase===phase)?.items||[]).filter(x=>x.levels.includes(p.license))}
function dailyPqsComplete(s){return !(s.pqsRequired||s.dailyPqs)||s.dailyPqs?.status==='Reviewed'}
async function dailyPqsAction(env,a,p,d,b){
 const s=d.shifts.find(x=>x.id===b.shiftId&&!x.archived);need(s,'Choose an existing training shift.');
 const items=dailyPqsItems(p,s.phase),old=s.dailyPqs;
 need(items.length,'No daily PQS is available for this phase.');
 if(['daily-pqs-save','daily-pqs-submit'].includes(b.action)){
  need(a.role==='trainee','Only the linked trainee completes the shown/practiced section.',403);
  need(!old||['Draft','Returned'].includes(old.status),'This submitted checklist is locked; request a correction.',409);
  need(Array.isArray(b.rows)&&b.rows.length===items.length&&new Set(b.rows.map(x=>x.id)).size===items.length&&items.every(x=>b.rows.some(v=>v.id===x.id)),'Provide the applicable checklist items exactly once.');
  const rows=items.map(item=>{const row=b.rows.find(x=>x.id===item.id);need([true,false,null].includes(row.shown)&&[true,false,null].includes(row.practiced),'Choose Yes, No, or unanswered for shown and practiced.');if(b.action==='daily-pqs-submit')need(typeof row.shown==='boolean'&&typeof row.practiced==='boolean','Answer shown and practiced for every item before submission.');return {id:item.id,title:item.title,group:item.group,shown:row.shown,practiced:row.practiced,traineeNotes:note(row.notes)}});
  if(b.action==='daily-pqs-submit')need(b.attest===true,'Confirm the trainee attestation.');
  s.dailyPqs={version:CATALOG.dailyPqs.version,source:CATALOG.dailyPqs.source,phase:s.phase,rows,status:b.action==='daily-pqs-submit'?'Submitted':'Draft',updatedAt:now(),updatedBy:a.email,revision:old?.revision||1,history:old?.history||[],traineeSignature:b.action==='daily-pqs-submit'?{by:a.email,name:a.name,actorId:a.id,at:now()}:null};
 }else if(b.action==='daily-pqs-sign'){
  await evaluator(env,a,p);need(a.role==='admin'||s.evaluator===a.email,'Only the shift evaluator or administrator can countersign this checklist.',403);
  need(old?.status==='Submitted','The trainee must submit this checklist first.',409);
  need(b.attest===true,'Confirm your evaluator attestation.');
  need(Array.isArray(b.rows)&&b.rows.length===items.length&&new Set(b.rows.map(x=>x.id)).size===items.length&&items.every(x=>b.rows.some(v=>v.id===x.id)),'Evaluate each applicable item exactly once.');
  const signature={by:a.email,name:a.name,actorId:a.id,at:now()};
  old.rows=old.rows.map(row=>{const v=b.rows.find(x=>x.id===row.id);need(['Demonstrated','Needs practice','Not observed','Not applicable'].includes(v.outcome),'Choose an evaluator outcome for every item.');if(['Needs practice','Not applicable'].includes(v.outcome))textValue(v.notes,'Reason or next practice plan');return {...row,outcome:v.outcome,evaluatorNotes:note(v.notes),evaluatorSignature:signature}});
  old.evaluatorSignature=signature;old.status='Signed';old.signedAt=signature.at;
 }else if(b.action==='daily-pqs-return'){
  await evaluator(env,a,p);need(a.role==='admin'||s.evaluator===a.email,'Only the shift evaluator or administrator can return this checklist.',403);
  need(old&&['Submitted','Signed'].includes(old.status),'Choose a submitted or signed checklist.',409);
  const reason=textValue(b.notes,'Correction reason');const snapshot=structuredClone({...old,history:undefined});old.history||=[];old.history.push({at:now(),by:a.email,reason,snapshot});
  old.status='Returned';old.returnReason=reason;old.revision=(old.revision||1)+1;delete old.evaluatorSignature;delete old.signedAt;old.traineeSignature=null;
  for(const row of old.rows){delete row.evaluatorSignature;delete row.outcome;delete row.evaluatorNotes;}
 }else throw new ApiError('Unknown daily PQS action.');
 s.pqsRequired=true;audit(d,a,b.action,{shiftId:s.id,checklistVersion:CATALOG.dailyPqs.version});
}

// REU operational policy. Historical evidence remains stored; current permissions apply to every request.
const REU_ONBOARDING=['hrOrientation','hrRelease','fit','im','cevo','map','process'];
const REU_ONBOARDING_LABELS={hrOrientation:'TargetSolutions orientation',hrRelease:'HR release to the FTO program',fit:'Fit testing',im:'IM training',cevo:'CEVO and non-emergency driving',map:'Map and response-area knowledge test',process:'FTO process explained'};
const REU_DOMAINS={learning:'Learning',ems:'EMS response',driving:'Driving',equipment:'Equipment',station:'Station duties',workHabits:'Work habits',attitude:'Attitude',patientCare:'Patient care',reportWriting:'Report writing'};
const REU_RATINGS=['Unacceptable','Needs Improvement','Acceptable','Good','Outstanding'];
const REU_FEEDBACK=['aware','receptive','goals','feedback','equipmentCheck','radio','patientCare','procedures','careChoices','learningSpeed','stationExpectations','stationCompleted','aladtecForms','responseForm','paperForms','eso','issues','scanning','beneficial','moreTime'];
const REU_FEEDBACK_LABELS=['Was your trainer aware of your shift?','Was your trainer receptive to training?','Were shift goals explained?','Did your trainer provide useful feedback?','Did your trainer perform an equipment check with you?','Did your trainer explain and demonstrate radio use?','Did your trainer allow appropriate patient care for your phase?','Were procedures explained?','Were patient-care choices explained?','Was your learning speed respected?','Were station-duty expectations explained?','Were station duties completed?','Were Aladtec form locations explained?','Were you told about the response log?','Were paper-form locations explained?','Was your trainer helpful with ESO?','Was your trainer helpful with issues?','Was paperwork scanning explained?','Was this shift beneficial?','Do you need more training time?'];
function rolesOf(m){return [...new Set((Array.isArray(m?.roles)?m.roles:[m?.role]).filter(r=>['admin','trainer','trainee'].includes(r)))]}
function selfTraining(c,a,p){return c.members.some(m=>m.email===a.email&&m.traineeId===p.id&&rolesOf(m).includes('trainee'))}
function independentAdmin(c,a,p){need(a.role==='admin','An administrator must make this decision.',403);need(!selfTraining(c,a,p),'Another administrator must approve your own training.',403)}
function holdActive(d){return (d.concerns||[]).some(x=>x.status!=='Cleared')}
function operationalStatus(d){if(d.release)return 'Approved for independent duty';if(holdActive(d))return 'Training on hold';if(!d.onboarding?.clearance)return 'Pre-ride onboarding';if(!d.assignment?.ftoEmail||!d.assignment?.firstShift)return 'Awaiting FTO assignment and scheduling';if(d.currentPhase===5)return d.testRecommendation?'Awaiting final test-out':'Final evaluation in progress';return 'Day / phase '+d.currentPhase+' in progress'}
function reuSubmitted(v){return ['Submitted','Signed','Reviewed'].includes(v?.status)}
function reuPaperwork(s){return [{type:'shift',label:'FTO trainee evaluation',record:s},{type:'response',label:'Trainee response / driving log',record:s.traineeResponse},{type:'feedback',label:'Trainee evaluation of trainer',record:s.trainerFeedback},{type:'pqs',label:'Daily PQS checklist',record:s.dailyPqs}]}
function reuPhaseBlockers(d,p,phase){const errors=[];if(holdActive(d))errors.push('Administrator review of a training concern is required.');const shifts=live(d.shifts).filter(s=>s.phase===phase);if(!shifts.length)errors.push('Record training and observed performance in this phase.');const defs=dailyPqsItems(p,phase);const completed=new Set(shifts.filter(s=>s.dailyPqs?.status==='Reviewed').flatMap(s=>s.dailyPqs.rows.filter(x=>x.outcome==='Demonstrated').map(x=>x.id)));if(defs.some(x=>!completed.has(x.id)))errors.push('Demonstrate every applicable daily PQS task and obtain administrator approval.');if(shifts.some(s=>!shiftComplete(s)))errors.push('All phase paperwork needs administrator approval.');const evaluations=shifts.filter(s=>s.status==='Reviewed');if(!evaluations.length||Object.keys(REU_DOMAINS).filter(k=>phase>2||!['patientCare'].includes(k)).filter(k=>phase>1||!['ems','reportWriting'].includes(k)).some(k=>{const v=evaluations.filter(s=>s.reuEvaluation?.ratings[k]!=null).at(-1)?.reuEvaluation?.ratings[k];return !Number.isInteger(v)||v<3}))errors.push('Every evaluation category needs an observed rating of Acceptable or higher.');return errors}
function reuReadiness(d,p,c){const hours=PHASES.map(id=>({id,title:CATALOG.phases[id-1].title,required:0,actual:Math.round(live(d.shifts).filter(s=>s.phase===id&&shiftComplete(s)).reduce((n,s)=>n+s.hours,0)*100)/100,approved:d.phaseReviews.some(v=>v.phase===id&&v.decision==='Advance')}));const sk=skills(p).map(s=>skillState(d,s));const blockers=[];if(!d.onboarding?.clearance)blockers.push('Complete pre-ride onboarding and administrator clearance.');if(holdActive(d))blockers.push('A training concern is on hold for administrator review.');if(!hours.every(x=>x.approved))blockers.push('The FTO must confirm completion of all five phases.');if(live(d.shifts).some(s=>!shiftComplete(s)))blockers.push('All training paperwork needs administrator approval.');if(!d.testRecommendation)blockers.push('The assigned FTO must recommend final test-out.');const passed=d.finalTest?.written?.passed&&d.finalTest?.practical?.passed;return {hours,skills:sk,lessons:{complete:modules(p).filter(m=>d.lessons[m.id]?.passed).length,total:modules(p).length},credentials:CATALOG.credentials.map(title=>({title,complete:live(d.credentials).some(x=>x.title===title&&x.verified)})),scenarios:CATALOG.scenarios.map(s=>({id:s.id,title:s.title,complete:!!d.scenarios.find(x=>x.scenarioId===s.id&&x.passed)})),actualEncounters:live(d.shifts).flatMap(s=>s.traineeResponse?.runs||[]).filter(x=>x.role==='Lead').length,pcrReviews:0,evaluators:new Set(d.shifts.map(s=>s.evaluator)).size,blockers,eligible:!blockers.length,passedExam:passed?{score:d.finalTest.written.score,at:d.finalTest.written.at}:null,finalized:!!d.release,assessments:{map:'Record an actual external assessment',written:'Agency-administered assessment evidence',practical:'Agency-administered assessment evidence'},status:operationalStatus(d)}}
async function approvedFtos(env,c){const result=[];for(const m of c.members.filter(m=>m.active!==false&&rolesOf(m).includes('trainer'))){const t=(await instructor(env,m.email)).value;if(t.appointment?.expires>=today()&&t.appointment.version===CATALOG.version&&LEVELS.includes(m.license))result.push({email:m.email,name:m.name,license:m.license,expires:t.appointment.expires})}return result}
async function reuAction(env,c,a,p,d,b){const action=b.action;
 if(action==='onboarding-item'){independentAdmin(c,a,p);need(REU_ONBOARDING.includes(b.item),'Choose a pre-ride requirement.');d.onboarding||={items:{},history:[]};need(!d.onboarding.clearance,'Revoke clearance before changing onboarding evidence.',409);const reference=textValue(b.reference,'Completion evidence reference',800);need(b.completed===true,'Only actual completed requirements may be verified.');if(b.item==='hrRelease')need(d.onboarding.items.hrOrientation,'Verify TargetSolutions orientation first.');if(!['hrOrientation','hrRelease'].includes(b.item))need(d.onboarding.items.hrRelease,'HR must release this hire to the Training Officer first.');if(b.item==='map')need(b.external===true,'The website map test is not yet developed. Record only an actual externally completed assessment.',409);if(['im','cevo'].includes(b.item)){need(/^\d{4}-\d{2}-\d{2}$/.test(b.completedDate)&&b.completedDate<=today(),'Enter the actual completion date.');need(d.attachments.some(f=>f.id===b.fileId&&f.scope==='admin-onboarding'&&f.formKind===b.item&&f.mime==='application/pdf'),'Attach the completed onboarding PDF.');textValue(b.evaluatorName,'Evaluator name',150);}d.onboarding.items[b.item]={by:a.email,name:a.name,at:now(),reference,external:b.external===true,...(['im','cevo'].includes(b.item)?{completedDate:b.completedDate,evaluatorName:b.evaluatorName,fileId:b.fileId}:{} )};}
 else if(action==='clear-first-ride'){independentAdmin(c,a,p);need(REU_ONBOARDING.every(k=>d.onboarding?.items[k]),'Verify HR release, fit testing, IM, CEVO, map assessment and FTO explanation first.',409);need(!holdActive(d),'Resolve the training hold before first-ride clearance.',409);d.onboarding.clearance={by:a.email,name:a.name,at:now(),notes:textValue(b.notes,'Clearance instructions')};}
 else if(action==='revoke-clearance'){independentAdmin(c,a,p);need(d.onboarding?.clearance,'No clearance recorded.');d.onboarding.history.push({clearance:d.onboarding.clearance,by:a.email,at:now(),reason:textValue(b.notes,'Reason')});d.onboarding.clearance=null;}
 else if(action==='assign-fto'){independentAdmin(c,a,p);need(d.onboarding?.clearance,'First-ride clearance must come before FTO assignment.',409);const f=(await approvedFtos(env,c)).find(x=>x.email===b.email);need(f&&LEVELS.indexOf(f.license)>=LEVELS.indexOf(p.license),'Select an active approved FTO qualified for this license.');need(!selfTraining(c,{email:f.email},p),'A trainee cannot be their own FTO.');need(Number.isFinite(Date.parse(b.firstShift)),'Enter the first / next scheduled training shift.');d.assignmentHistory||=[];if(d.assignment)d.assignmentHistory.push({...d.assignment,replacedAt:now()});d.assignment={ftoEmail:f.email,ftoName:f.name,firstShift:new Date(b.firstShift).toISOString(),by:a.email,at:now(),reason:textValue(b.notes,'Assignment or coverage reason')};}
 else if(action==='flag-concern'){await evaluator(env,a,p);d.concerns||=[];d.concerns.push({id:crypto.randomUUID(),title:textValue(b.title,'Concern title',150),details:textValue(b.details,'Observed concern'),shiftId:b.shiftId||null,actionTaken:textValue(b.actionTaken,'Action already taken'),requested:note(b.requested),by:a.email,name:a.name,at:now(),status:'Open',history:[]});}
 else if(action==='review-concern'){independentAdmin(c,a,p);const v=d.concerns?.find(x=>x.id===b.concernId);need(v,'Choose a concern.');need(['Cleared','Remediation required','Duties restricted'].includes(b.decision),'Select a review outcome.');v.history.push({status:v.status,by:a.email,at:now(),notes:textValue(b.notes,'Review decision and instructions')});v.status=b.decision;v.review={by:a.email,name:a.name,at:now(),notes:b.notes};}
 else if(action==='request-correction'){need(['trainer','trainee'].includes(a.role),'Use the appropriate working role to request a correction.',403);const s=d.shifts.find(x=>x.id===b.shiftId&&!x.archived);need(s,'Choose a shift.');need(['shift','response','feedback','pqs'].includes(b.type),'Choose the form.');if(a.role==='trainee')need(['response','feedback','pqs'].includes(b.type),'Only request correction of your own submissions.',403);if(a.role==='trainer')need(b.type==='shift'||b.type==='pqs','Private trainee feedback is not available to FTOs.',403);const v=reuPaperwork(s).find(x=>x.type===b.type).record;need(v&&v.status!=='Draft','Choose a submitted form.');d.corrections||=[];need(!d.corrections.some(x=>x.shiftId===s.id&&x.type===b.type&&x.status==='Open'),'A correction request is already open.');d.corrections.push({id:crypto.randomUUID(),shiftId:s.id,type:b.type,by:a.email,role:a.role,at:now(),reason:textValue(b.notes,'Correction request'),status:'Open'});}
 else if(action==='review-paperwork'){independentAdmin(c,a,p);const s=d.shifts.find(x=>x.id===b.shiftId&&!x.archived);need(s,'Choose a shift.');const v=reuPaperwork(s).find(x=>x.type===b.type)?.record;need(v&&reuSubmitted(v),'Choose submitted paperwork.');need(['Approve','Return'].includes(b.decision),'Choose Approve or Return.');snapshotUpdate(s);v.reviewHistory||=[];v.reviewHistory.push({status:v.status,by:a.email,at:now(),notes:textValue(b.notes,'Review notes')});if(b.decision==='Approve'){if(b.type==='pqs')need(v.evaluatorSignature,'FTO must countersign first.');v.status='Reviewed';v.review={by:a.email,name:a.name,at:now(),notes:b.notes};}else{if(b.type==='pqs'){v.history||=[];v.history.push({at:now(),by:a.email,reason:b.notes,snapshot:structuredClone({...v,history:undefined})});delete v.evaluatorSignature;v.traineeSignature=null;for(const row of v.rows){delete row.outcome;delete row.evaluatorSignature;delete row.evaluatorNotes}}v.status=b.type==='shift'?'Draft':'Returned';v.returnReason=b.notes;v.review={by:a.email,at:now(),notes:b.notes};}for(const request of d.corrections||[])if(request.shiftId===s.id&&request.type===b.type&&request.status==='Open'){request.status='Handled';request.review={by:a.email,at:now(),decision:b.decision,notes:b.notes}}}
 else if(action==='fto-advance'){await evaluator(env,a,p);need(!selfTraining(c,a,p),'You cannot advance your own training.',403);need(!holdActive(d),'Administrator review must lift the training hold.',409);const errors=reuPhaseBlockers(d,p,d.currentPhase);need(!errors.length,errors.join(' '),409);d.phaseReviews.push({phase:d.currentPhase,decision:'Advance',by:a.email,name:a.name,at:now(),notes:textValue(b.notes,'Competence evidence and next objectives')});if(d.currentPhase<5)d.currentPhase++;else d.testRecommendation={by:a.email,name:a.name,at:now(),notes:b.notes};}
 else if(action==='response'||action==='feedback'){
  need(a.role==='trainee','Only the linked trainee completes this form.',403);const s=d.shifts.find(x=>x.id===b.shiftId&&!x.archived);need(s,'Choose a training shift.');const key=action==='response'?'traineeResponse':'trainerFeedback',old=s[key];need(!old||['Draft','Returned'].includes(old.status),'An administrator must return submitted paperwork before correction.',409);need(b.attest===true||b.draft===true,'Confirm your signed submission.');const form=b.form;let fields;
  if(action==='response'){need(Array.isArray(form.runs)&&form.runs.length<=100,'Provide a valid response / driving log.');const runs=form.runs.map(x=>{need(['Drive','Observe','Assist','Lead'].includes(x.role)&&['ALS','LALS','BLS'].includes(x.level),'Choose role and level of care.');need(/^\d{4}-\d{2}-\d{2}$/.test(x.date),'Enter the response date.');return {date:x.date,reference:textValue(x.reference,'Run number',100),role:x.role,priority:textValue(x.priority,'Response priority',100),preceptor:textValue(x.preceptor,'Preceptor',200),level:x.level}});fields={runs,noCalls:form.noCalls===true};need(b.draft||runs.length||fields.noCalls,'Enter responses or confirm no calls.');}
  else {need(REU_FEEDBACK.every(k=>['Yes','No','Not observed'].includes(form.answers?.[k]))||b.draft,'Answer every trainer-evaluation item.');fields={answers:Object.fromEntries(REU_FEEDBACK.map(k=>[k,form.answers?.[k]||'Not observed'])),topics:note(form.topics),skills:note(form.skills),comments:note(form.comments),improvements:note(form.improvements)};if(!b.draft){textValue(form.skills,'Skills performed');textValue(form.comments,'Comments about your trainer');}}
  s[key]={...fields,history:old?.history||[],status:b.draft?'Draft':'Submitted',by:a.email,name:a.name,at:now(),signature:b.draft?null:{by:a.email,name:a.name,actorId:a.id,at:now()}};
 }else return false;
 audit(d,a,action,{role:a.role,phase:d.currentPhase,shiftId:b.shiftId||null});invalidate(d);return true;
}

const OWNER=CATALOG.bootstrapOwnerEmail,CONFIG='academy/config.json',PHASES=[1,2,3,4,5],LEVELS=['EMT','AEMT','Paramedic'];
const now=()=>new Date().toISOString(),today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Detroit'}).format(new Date());
const out=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
class ApiError extends Error{constructor(message,status=400){super(message);this.status=status}}
function need(test,message,status=400){if(!test)throw new ApiError(message,status)}
function textValue(v,label,max=4000){need(typeof v==='string'&&v.trim()&&v.length<=max,`${label} is required (maximum ${max} characters).`);return v.trim()}
const note=v=>typeof v==='string'?v.trim().slice(0,8000):'';
async function body(request){const raw=await request.text();need(raw.length<=2000000,'Request is too large.',413);try{return JSON.parse(raw)}catch{throw new ApiError('Invalid request data.')}}
async function object(env,key,initial){const o=await env.BUCKET.get(key);return {etag:o?.etag||null,value:o?await o.json():initial}}
async function persist(env,key,value,etag){const r=await env.BUCKET.put(key,JSON.stringify(value),etag?{onlyIf:{etagMatches:etag}}:{onlyIf:{etagDoesNotMatch:'*'}});need(r,'Someone updated this record. Refresh and try again.',409);return r.etag}
function audit(d,a,action,detail={}){d.audit||=[];d.audit.push({id:crypto.randomUUID(),at:now(),actor:a.email,actorId:a.id,role:a.role,action,...detail})}
function freshData(id){return {id,version:CATALOG.version,currentPhase:1,lessons:{},lessonAttempts:[],shifts:[],skills:[],scenarios:[],credentials:[],remediation:[],phaseReviews:[],phaseRequests:[],examAttempts:[],examAuthorization:null,activeExam:null,release:null,audit:[],attachments:[]}}
async function configuration(env){let c=await object(env,CONFIG,null);if(!c.value){const prior=(await object(env,'program/config.json',{state:{},members:[]})).value;const people=(prior.state?.people||[]).filter(p=>!p.demo&&p.active!==false).map(p=>({id:String(p.id),name:p.name,license:LEVELS.includes(p.license)?p.license:'EMT',pathway:'Standard',startDate:today(),active:true}));if(!people.length)people.push({id:'1',name:'Trainee',license:'EMT',pathway:'Standard',startDate:today(),active:true});const members=(prior.members||[]).filter(m=>m.email!==OWNER&&m.active!==false).map(m=>({email:m.email,name:m.displayName||m.email,role:m.role==='fto'?'trainer':m.role,traineeId:String(m.traineeId||''),assignedIds:(m.assignedTraineeIds||[]).map(String),license:m.evaluatorLicense||''}));const v={version:CATALOG.version,people,members,adoption:null,examVersion:1,examPublished:false,passPercent:80,examQuestions:structuredClone(CATALOG.exam),referenceRelease:[],audit:[]};try{c={value:v,etag:await persist(env,CONFIG,v,null)}}catch(e){if(e.status!==409)throw e;c=await object(env,CONFIG,null)}}return c}
function actor(request,c){const id=request.headers.get('oai-authenticated-user-id'),email=(request.headers.get('oai-authenticated-user-email')||'').trim().toLowerCase();need(id&&email,'Sign in with your REU account.',401);const m=c.members.find(m=>m.email===email&&m.active!==false);need(email===OWNER||m,'This account has no REU training role.',403);let name=request.headers.get('oai-authenticated-user-full-name')||m?.name||'Noah Wollet';if(request.headers.get('oai-authenticated-user-full-name-encoding')==='percent-encoded-utf-8')try{name=decodeURIComponent(name)}catch{}const roles=rolesOf(m);if(email===OWNER&&!roles.includes('admin'))roles.unshift('admin');const role=assignedAccess(m,email===OWNER);need(role&&roles.includes(role),'This account has no assigned access level.',403);const requestedRole=request.headers.get('X-REU-Role');need(!requestedRole||requestedRole===role,'Role switching is disabled. Refresh to use your assigned access level.',403);return {...m,id,email,name,roles,role,owner:email===OWNER}}

function assigned(a,p){return a.role==='admin'||(a.role==='trainee'&&a.traineeId===p.id)||a.role==='trainer'}
